const history = ($input.first().json.records || []).sort((a, b) => a.fields.month.localeCompare(b.fields.month));
const children = ($input.all()[1]?.json?.records || []);

const active = children.filter(c => (c.fields.status || '').toLowerCase() !== 'inactive');
const waitlist = 5;

let message = `📈 *Monthly Enrollment Report*\n`;
message += `Date: ${new Date().toISOString().split('T')[0]}\n\n`;

message += `*Current Status:*\n`;
message += `Active enrollment: ${active.length} children\n`;
message += `Waitlist: ${waitlist} families\n\n`;

message += `*6-Month Trend:*\n`;
const last6 = history.slice(-6);
for (const h of last6) {
  const f = h.fields;
  const bar = '█'.repeat(f.total_enrolled);
  message += `${f.month}: ${bar} ${f.total_enrolled} enrolled | $${f.monthly_revenue?.toLocaleString()}\n`;
}

if (last6.length >= 2) {
  const first = last6[0].fields;
  const last = last6[last6.length - 1].fields;
  const revChange = ((last.monthly_revenue - first.monthly_revenue) / first.monthly_revenue * 100);
  message += `\n*Revenue:* $${last.monthly_revenue?.toLocaleString()}/mo`;
  message += `\n6-month change: ${revChange >= 0 ? '+' : ''}${revChange.toFixed(1)}%`;
}

// Enrolled by room
const roomCounts = {};
for (const c of active) {
  const room = c.fields.age_group || 'Unassigned';
  roomCounts[room] = (roomCounts[room] || 0) + 1;
}
message += `\n\n*By Room:*\n`;
const roomLabels = {'Toddler': 'Toddler (2/6)', 'Preschool': 'Preschool (4/10)', 'Pre-K': 'Pre-K (2/12)', 'Infant': 'Infant (0/4)'};
for (const [room, count] of Object.entries(roomCounts)) {
  message += `• ${room}: ${count} ${roomLabels[room] || ''}\n`;
}

const capacity = 32;
const utilization = (active.length / capacity * 100).toFixed(0);
message += `\n*Capacity utilization:* ${utilization}% (${active.length}/${capacity})`;

return [{json: {message, active_count: active.length, waitlist, utilization: parseInt(utilization)}}];
